export function startReconcile(db: Db, port: PaypalPort): void {
  const tick = async () => {
    try {
      const orders = db.prepare('SELECT DISTINCT paypal_order_id FROM captures').all() as Array<{ paypal_order_id: string }>
      for (const o of orders) {
        const ledger = await port.getOrder(String(o.paypal_order_id))
        for (const r of ledger.refunds) {
          run(db, 'INSERT OR IGNORE INTO refunds (paypal_refund_id, paypal_order_id, amount) VALUES (?, ?, ?)', r.id, String(o.paypal_order_id), r.amount)
        }
      }
    } catch {
      // try again on the next tick
    }
  }
  setInterval(tick, 2000).unref()
}
